        extrato.put("itens", itens);
        extrato.put("palestrasMinutos", palestrasMinutos);
        extrato.put("minicursosMinutos", minicursosMinutos);
        extrato.put("totalMinutos", totalMinutos);
        extrato.put("aproveitadoMinutos", aproveitadoMinutos);

        ctx.json(extrato);
    } catch (SQLException e) {
        ctx.status(500);
    }
});

