                     psSala.setString(1, salaId);
                     ResultSet rsSala = psSala.executeQuery();
                     if (rsSala.next()) {
                         int cap = rsSala.getInt("capacidade");
                         if (newVagas > cap) {
                             ctx.status(422);
                             ctx.json(Map.of("erro", "VAGAS_ACIMA_DA_CAPACIDADE", "mensagem", "Vagas acima da capacidade da sala"));
