                     linha.put("ocupacaoPercentual", ocupacaoPercentual);
                     linha.put("frequenciaPercentual", frequenciaPercentual);
                     painel.add(linha);
                 }
             } catch (SQLException e) {
                 ctx.status(500);
             }
 
             ctx.json(painel);
         });
 
