                 PreparedStatement psCheck = conn.prepareStatement("SELECT 1 FROM inscricoes WHERE atividadeId = ? AND participanteId = ? AND status IN ('confirmada', 'em_espera', 'convocada')");
                 psCheck.setString(1, atividadeId);
