                             for (Map<String, String> ne : encontrosNew) {
                                 OffsetDateTime nStart = OffsetDateTime.parse(ne.get("inicio"));
                                 OffsetDateTime nEnd = OffsetDateTime.parse(ne.get("fim"));
                                 if (nStart.isBefore(exEnd) && exStart.isBefore(nEnd)) {
                                     hasConflict = true;
