                     int vagas = rs.getInt("vagas");
 
                     int ocupadas = 0;
                     int emEspera = 0;
                     try (PreparedStatement psIns = conn.prepareStatement("SELECT status, count(*) FROM inscricoes WHERE atividadeId = ? GROUP BY status")) {
                         psIns.setString(1, atvId);
