                     linha.put("vagas", vagas);
                     linha.put("ocupadas", ocupadas);
                     linha.put("emEspera", emEspera);
                     linha.put("ocupacaoPercentual", ocupacaoPercentual);
                     linha.put("frequenciaPercentual", frequenciaPercentual);
                     painel.add(linha);
                 }
             } catch (SQLException e) {
                 ctx.status(500);
             }
 
             ctx.json(painel);
